entries[159610] = { ["name"] = "Gefäß der krabbelnden Schatten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, einen flüchtigen Schattenweber zu beschwören, der auf das Ziel zukriecht, bei Kontakt explodiert und 64 Schattenschaden verursacht, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. (5s Abklingzeit)\nVerkaufspreis:" }
entries[159611] = { ["name"] = "Ratztunks großer roter Knopf", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Drückt den großen roten Knopf, um eine Geschosssalve abzuschießen, die ( 1 * 271 ) Feuerschaden verursacht, die unter allen Gegnern im Wirkungsbereich aufgeteilt werden. Bei mehreren Gegnern ist der Schaden erhöht. (2 Min Abklingzeit)\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[159612] = { ["name"] = "Azerokks resonierendes Herz", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 9.\nAnlegen: Eure Angriffe haben eine Chance, sich mit dem Splitter zu harmonisieren, was Eure Beweglichkeit für 15 Sek. um 24 erhöht.\nSchließt in Saison 2 von The War Within alle Dungeons auf Mythisch+ und der Schlüsselsteinstufe 12 innerhalb des Zeitlimits ab.\nVerkaufspreis:" }
entries[159614] = { ["name"] = "Segen der Sturmbeschwörerin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nBenutzen: Platziert für 10 Sek. einen Zauberschutz auf dem Boden, der Euer Tempo um 50 und Eure Bewegungsgeschwindigkeit um 50 erhöht, solange Ihr Euch innerhalb seines Effektbereichs aufhaltet. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[159615] = { ["name"] = "Zünder der Brandmagierin", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Entzündet die Lunte und gewährt alle 4 Sek. 15 Tempo. Tempo wird nach 20 Sek. entfernt. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[159616] = { ["name"] = "Blutverkrusteter Schlachtblock", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nAnlegen: Eure Angriffe haben eine Chance, Eure Klinge zu schärfen und Euch 15 Sek. lang 36 kritischen Trefferwert zu gewähren.\nVerkaufspreis:" }
entries[159617] = { ["name"] = "Glänzend goldenes Gefieder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nBenutzen: Erhöht Eure Vielseitigkeit 20 Sek. lang um 38 . (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[159618] = { ["name"] = "Mchimbas Ritualbandagen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nBenutzen: Wickelt Euch in rituelle Bandagen, die 6 Sek. lang [ 559 * (1 + Vielseitigkeit)] Schaden absorbieren. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[159619] = { ["name"] = "Salzige Seepocke", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nAnlegen: Eure Angriffe haben eine Chance, 'Erstickendes Meerwasser' hervorzurufen, das im Verlauf von 6 Sek. ( 4 * 6) Naturschaden verursacht. Wenn das Ziel stirbt, während es an 'Erstickendes Meerwasser' leidet, breitet sich der Effekt auf alle Ziele innerhalb von 8 Metern aus.\nVerkaufspreis:" }
entries[159620] = { ["name"] = "Muschel des dunklen Flüsterns", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Zauber haben eine Chance, Euren kritischen Trefferwert für 15 Sek. um 37 zu erhöhen.\nVerkaufspreis:" }
entries[159621] = { ["name"] = "Persönlicher Anker", ["text"] = "Einzigartig\n\"Es gibt viele wie den hier, aber der ist meiner.\"\nVerkaufspreis:" }
entries[159622] = { ["name"] = "Hadals Nautilus", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, an der Position Eures Ziels eine Wasserfontäne zu erzeugen. Sie bricht nach 2 Sek. aus und verursacht 23 Naturschaden, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. (3s Abklingzeit)\nVerkaufspreis:" }
entries[159623] = { ["name"] = "Fernrohr des Scharfschützen", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, das Ziel mit 'Tote voraus' zu markieren. Durch Angriffe auf das markierte Ziel wird Euer kritischer Trefferwert für 10 Sek. um 7 erhöht. Dieser Effekt ist bis zu 5-mal stapelbar.\nVerkaufspreis:" }
entries[159624] = { ["name"] = "Vermoderte Voodoopuppe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nBenutzen: Wedelt demonstrativ mit Eurer Voodoopuppe in Richtung Eures Ziels und verursacht im Verlauf von 6 Sek. 126 Schattenschaden sowie nach 6 Sek. zusätzlich 202 Schattenschaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[159625] = { ["name"] = "Phiole mit beseeltem Blut", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 9.\nBenutzen: Trinkt aus der Phiole und gewinnt (3 * 9 ) Stärke hinzu, die im Verlauf von 18 Sek. verfällt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[159626] = { ["name"] = "Nachhaltige Sporenkapseln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke]\nAnlegen: Eure Angriffe sowie Angriffe gegen Euch haben eine Chance, Sporen zu erschaffen, die 4 Sek. lang wachsen und dann platzen. Dabei heilen sie Euch um 75 Gesundheit und verursachen 21 Schaden, der unter allen Gegnern in der Nähe aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht.\nVerkaufspreis:" }
entries[159627] = { ["name"] = "Jes' Knurrer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Stärke\nBenutzen: Stößt ein motivierendes Heulen aus, das 12 Sek. lang 60 Vielseitigkeit gewährt, die gleichmäßig auf Euch und bis zu 4 Verbündete in der Nähe aufgeteilt wird. Für jeden von Euch motivierten Verbündeten gewinnt Ihr zusätzlich 7 Vielseitigkeit hinzu. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[159628] = { ["name"] = "Kanonenkugelwerfer von Kul Tiras", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Beweglichkeit\nAnlegen: Eure Angriffe haben eine Chance, für 10 Sek. eine Kanonenbatterie an Eure Seite zu beschwören, die insgesamt ( 11 * 5) Feuerschaden verursacht, der gleichmäßig unter allen Gegnern in einem kegelförmigen Bereich vor ihr aufgeteilt wird. Bei mehreren Gegnern ist der Schaden erhöht. (5s Abklingzeit)\nVerkaufspreis:" }
entries[159630] = { ["name"] = "Unheilfeuerzweig", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\nErhöht Eure Meisterschaftswertung um + 9.\nBenutzen: Entfacht Eure Seele und gewinnt (100 * 0 ) Intelligenz hinzu, die im Verlauf von 20 Sek. oder beim Erleiden von Schaden verfällt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[159631] = { ["name"] = "Lady Kronsteigs Spieluhr", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 Intelligenz\nAnlegen: Eure Schaden verursachenden Zauber haben eine Chance, einen dissonanten Akkord anzuschlagen, der einem Gegner in der Nähe 26 Schaden zufügt.\n\nEure Heilzauber haben eine Chance, einen harmonischen Akkord anzuschlagen, der einen verletzten Verbündeten in der Nähe um 39 Gesundheit heilt.\n\nKronsteigs Vermächtnis (0/2)\nLord Kronsteigs Siegelring\nLady Kronsteigs Spieluhr\n(2) Set : Wenn Ihr einen dissonanten Akkord oder einen harmonischen Akkord auslöst, besteht eine Chance von 40%, dass der jeweils andere Akkord mit 60% der Kraft ausgelöst wird.\nVerkaufspreis:" }
