entries[159825] = { ["name"] = "Schriftrolle des Entriegelns", ["text"] = "Benutzen: Ermöglicht das Öffnen von Schlössern, die eine Fertigkeit von bis zu 50 im Schlossknacken benötigen. Dieser Vorgang verbraucht die Schriftrolle.\nBenötigt Inschriftenkunde von Kul Tiras (1)\nVerkaufspreis:" }
