entries[159827] = { ["name"] = "Bomb-samdis Mojobomben", ["text"] = "Benutzen: Fügt allen Gegnern in einem Radius von 5 Metern 315 Feuerschaden zu. (1 Min Abklingzeit)\n\"Die jüngsten Gegenmaßnahmen des Goblintrupps gegen Bluttrolle.\"" }
entries[159828] = { ["name"] = "Uralte Münze", ["text"] = "Questgegenstand\n\"Diese Goldmünze zieren Motive aus einer uralten Trollzivilisation.\"" }
entries[159829] = { ["name"] = "Gürtelverzauberung: Miniaturisierter Plasmaschild", ["text"] = "Benutzen: Bringt dauerhaft ein spezialisiertes Gerät an Eurem Gürtel an, mit dem Ihr für 10 Sek. einen Absorptionsschild um Euch erschaffen könnt.\n\nNur der Gürtel des Ingenieurs kann modifiziert werden und wird dadurch seelengebunden." }
entries[159830] = { ["name"] = "Frisches Sternmoos", ["text"] = "Questgegenstand\nEinzigartig (20)\n\"Es ist frisch!\"" }
entries[159831] = { ["name"] = "Verschlossene Kiste von Kul Tiras", ["text"] = "Questgegenstand\n\"Mit einem Siegel aus Kul Tiras versehen.\"" }
entries[159832] = { ["name"] = "Schluchtkäfer", ["text"] = "Questgegenstand\nDauer: 1 Stunde (Realzeit)\n\"Schluchtkäfer sind die bevorzugte Nahrungsquelle der Ranishu. Aber sein wir mal ehrlich... Die fressen auch wirklich alles.\"" }
entries[159833] = { ["name"] = "Glimmendes Bündel Sternmoos", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Facht die glimmenden Blätter an, sodass der Rauch den Bereich läutert. (10 Sek. Abklingzeit)\n\"Dicke, beißende Rauchwolken verschaffen Eurem Geist etwas Ruhe.\"" }
entries[159834] = { ["name"] = "Die Stolz von Kul Tiras", ["text"] = "Questgegenstand\n\"Im Maßstab 1:100 aufwendig gearbeitet.\"" }
entries[159835] = { ["name"] = "Schiffslogbuch", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein Bündel durchnässter Papiere, von denen die meisten unleserlich sind. Sie enthalten Informationen über die Fracht des Schiffs.\"" }
entries[159836] = { ["name"] = "Späherkarte", ["text"] = "Questgegenstand\nEinzigartig\n\"Auf dieser groben Karte der örtlichen Küste sind viele Notizen verzeichnet.\"" }
entries[159837] = { ["name"] = "Nicht abgeschickter Brief", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein zerknüllter Brief, unvollendet und niemals abgeschickt. Er war eindeutig für jemanden in Sturmwind bestimmt.\"" }
entries[159839] = { ["name"] = "Spinnenseide", ["text"] = "Questgegenstand" }
entries[159840] = { ["name"] = "Teebus Säbel der Sengflammen", ["text"] = "Wird beim Anlegen gebunden\nEinhändig Schwert\n6 - 12 Schaden Geschwindigkeit 2.60\n(3.5 Schaden pro Sekunde)\nHaltbarkeit 110 / 110\nTrefferchance: Überzieht ein Ziel mit 6 Feuerschaden.\nVerkaufspreis:" }
entries[159841] = { ["name"] = "Foliant der Verhexung: Skelettjungtier", ["text"] = "Wird beim Aufheben gebunden\nKlassen: Schamane\nBenutzen: Lehrt 'Verhexung: Skelettjungtier'.\nVerwandelt den Gegner für 1 Min. in ein Skelettjungtier. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Maximal 1 Ziel. Kann nur auf Humanoide und Wildtiere angewandt werden.\nVerkaufspreis:" }
entries[159842] = { ["name"] = "Haihappens Lieblingskekse", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Haihappen beschwört und für sich gewinnt.\nBeschwört Haihappen mit einem leckeren Keks oder gibt ihn wieder frei. Dieses Reittier passt sich Eurer Reitfertigkeit und Eurem Aufenthaltsort an.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Haihappen ist jedem treu ergeben, der stets Kekse für ihn hat.\"\nBeute von:\nHarlan der Schmierige\nZone:\nFreihafen (Mythisch)\n\nSchatz:\nSchatz des Herausforderers\nZone:\nFreihafen" }
