entries[160249] = { ["name"] = "Vorratsbündel", ["text"] = "Questgegenstand\n\"Ein kleines Bündel Materialien. Stoff, Holz, Nägel... allerhand nützliche Dinge.\"" }
entries[160250] = { ["name"] = "Tote pollenbedeckte Wespe", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Tot, aber völlig von Pollen bedeckt.\"" }
entries[160251] = { ["name"] = "Pestrufers Sterbefix", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Der einfachste Ausweg.\n\nWARNUNG: Wird Euch töten. (3 Min Abklingzeit)\n\"Eine zugepfropfte Phiole mit einer blassen, unregelmäßig herumwirbelnden Flüssigkeit. Auf dem Etikett ist ein Schädel abgebildet.\"" }
entries[160252] = { ["name"] = "Jahdens Trank der Pflanzengestalt", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Verwandelt Euch in eine Blume, damit Wespen Eure Pollen ernten können." }
entries[160253] = { ["name"] = "Reines Wasserpartikel", ["text"] = "Questgegenstand\n\"Im Inneren glitzert ein noch nicht verderbter Kern.\"" }
entries[160260] = { ["name"] = "Kanonenkugel der Nebelfockfreibeuter", ["text"] = "Questgegenstand\n\"Schwer, unhandlich und perfekt für Eure Zwecke.\"" }
entries[160261] = { ["name"] = "Seele der See", ["text"] = "Wird beim Aufheben gebunden\nFinger\n+4 Ausdauer\n+ 8 Vielseitigkeit\nErhöht Eure Meisterschaftswertung um + 6.\nVerkaufspreis:" }
entries[160262] = { ["name"] = "\"Relikt der Schöpfer\"", ["text"] = "Wird beim Aufheben gebunden\nSchmuck\nErhöht Eure Meisterschaftswertung um + 7.\nAnlegen: Eure Zauber und Fähigkeiten haben eine Chance, Euren Primärwert für 15 Sek. um 10 zu erhöhen.\nVerkaufspreis:" }
entries[160263] = { ["name"] = "Schneepelzzerfleischer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+6 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Angriffe haben eine Chance, einen Wirbel aus geschärften Klauen hervorzurufen und so 50 körperlichen Schaden zu verursachen, der gleichmäßig unter allen Gegnern innerhalb von 8 Metern aufgeteilt wird.\nVerkaufspreis:" }
