entries[160299] = { ["name"] = "Glimmendes Bündel Sternmoos", ["text"] = "Questgegenstand\nEinzigartig\nBenutzen: Facht die glimmenden Blätter an, sodass der Rauch den Bereich läutert. (10 Sek. Abklingzeit)\n\"Dicke, beißende Rauchwolken verschaffen Eurem Geist etwas Ruhe.\"" }
entries[160301] = { ["name"] = "Widerlich feuchte Blume", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Sie enthält keine Pollen, dafür aber eine Menge schleimiges Zeug.\"" }
entries[160302] = { ["name"] = "Schachtel mit Keksen", ["text"] = "Questgegenstand\n\"Mmm. Sie riechen köstlich!\"" }
entries[160307] = { ["name"] = "Raals Verhexstab", ["text"] = "Questgegenstand\nBenutzen: Verwandelt das Ziel für 5 Sek. in einen Sauriden. Während das Ziel verhext ist, ist es handlungsunfähig und kann weder angreifen noch Zauber wirken. Schaden kann den Effekt beenden. Kann nur auf Humanoide und Wildtiere angewandt werden. (5 Sek. Abklingzeit)" }
entries[160314] = { ["name"] = "Halskette eines Matrosen", ["text"] = "Questgegenstand\nEinzigartig\n\"Eine abgetragene Goldhalskette, die jetzt von Seetang bedeckt ist.\"" }
entries[160316] = { ["name"] = "Dunkeleisenkuriosität", ["text"] = "Questgegenstand\n\"Ein Relikt der Dunkeleisenzwerge, das die Tortollaner interessieren wird.\"" }
entries[160317] = { ["name"] = "V-300-Seriennummernschild", ["text"] = "Questgegenstand\n\"Eine Reihe Ziffern und Buchstaben sind darauf eingraviert.\"" }
entries[160322] = { ["name"] = "Haufen Erz", ["text"] = "Wird beim Aufheben gebunden\n\"Ein Haufen Erz aus Zandalar und Kul Tiras.\"\n<Zum Öffnen rechtsklicken>" }
entries[160323] = { ["name"] = "Vol'jins Gleve", ["text"] = "Questgegenstand\n\"Ein Meisterwerk der Shado-Pan-Handwerkskunst.\"" }
entries[160324] = { ["name"] = "Murrender Sack", ["text"] = "Wird beim Aufheben gebunden\n\"Offenbar bewegt sich darin etwas...\"\n<Zum Öffnen rechtsklicken>" }
entries[160325] = { ["name"] = "Zitternder Sack", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 7 tagen (Realzeit)\n\"Eine zuckende Masse aus transmutiertem Fleisch.\"" }
entries[160326] = { ["name"] = "Glitzerndes Schießpulver", ["text"] = "Questgegenstand\n\"Dieses faszinierende Pulver fühlt sich warm an.\"" }
entries[160327] = { ["name"] = "Schriftrolle der harmonischen Flossen", ["text"] = "Questgegenstand\n\"Seltsame Konsistenz.\"" }
